from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify the start and end indices of each separate group of nested parentheses
    groups = []
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                groups.append((start, i))

    # Step 3: Extract each separate group using the indices and add them to the list
    separate_groups = []
    for start, end in groups:
        separate_groups.append(paren_string[start:end+1])

    # Step 4: Return the list of separate groups
    return separate_groups

